using System;
using UnityEngine;
namespace SpatialWallpaper.Blueprint {
 public sealed class BlueprintEnvironment:MonoBehaviour {
  BlueprintScene scene;BlueprintTerrain terrain;BlueprintWeather weather;BlueprintClock clock=new BlueprintClock();ContinuousRenderDemand demand;float nextLight,lastHour=float.NaN;string lastMode;bool configured;public float Hour=>clock.VisibleHour;public float CycleHour=>clock.CycleHour;
  public void Configure(BlueprintScene value){scene=value;clock=new BlueprintClock();lastMode=null;lastHour=float.NaN;if(scene.Settings.TimeMode=="cycle"&&scene.Work!=null&&scene.Work.SourceHash==scene.Document.SourceHash){clock.RestoreCycle(BlueprintPlayback.Read(BlueprintLibrary.Root,scene.Work.WorkId,scene.Work.RevisionId,scene.Settings.Hour));lastMode="cycle";lastHour=scene.Settings.Hour;}if(!terrain)terrain=gameObject.AddComponent<BlueprintTerrain>();if(!weather)weather=gameObject.AddComponent<BlueprintWeather>();if(!demand)demand=gameObject.AddComponent<ContinuousRenderDemand>();terrain.Invalidate();weather.Invalidate();configured=true;Apply();}
  public void PersistPlayback(){if(scene&&scene.Work!=null&&scene.Document!=null&&scene.Work.SourceHash==scene.Document.SourceHash&&scene.Settings.TimeMode=="cycle")try{BlueprintPlayback.Write(BlueprintLibrary.Root,scene.Work.WorkId,scene.Work.RevisionId,clock.CycleHour);}catch(Exception e){Debug.LogWarning("Blueprint playback phase: "+e.Message);}}
  public void Apply(){if(!configured)return;var settings=scene.Settings;settings.Validate();if(settings.TimeMode=="cycle"&&(lastMode!="cycle"||lastHour!=settings.Hour))clock.RestoreCycle(settings.Hour);lastMode=settings.TimeMode;lastHour=settings.Hour;scene.Lighting.Weather=settings.Weather;terrain.Apply(scene,settings);weather.Apply(scene,settings);demand.SetInterval(settings.FrameRate==60?1:settings.FrameRate==30?2:4);demand.enabled=settings.WaterMotion||settings.LeavesMotion||settings.Fireflies||settings.Smoke||settings.Weather=="rain"||settings.Weather=="snow"||settings.TimeMode!="fixed";nextLight=0;}
  void Update(){if(!configured||!scene.Ready)return;var s=scene.Settings;bool paused=Time.timeScale==0;float hour=clock.Sample(s,DateTimeOffset.Now,Time.unscaledDeltaTime,paused);weather.SetPaused(paused);if(paused)return;Shader.SetGlobalFloat("_BlueprintWindStrength",s.LeavesMotion?s.Wind:0);if(Time.unscaledTime>=nextLight){nextLight=Time.unscaledTime+.15f;scene.Lighting.Apply(s.Look,s.Quality,hour);weather.Hour(hour);float night=1-Mathf.SmoothStep(0,1,Mathf.Clamp01(Mathf.Sin((hour-6)/12*Mathf.PI)*3));scene.Lighting.WindowGlow(s.WarmWindows,night);}}
  void OnDisable(){PersistPlayback();Shader.SetGlobalFloat("_BlueprintWindStrength",0);}
 }
}
